const paths={up:'M12 19V5m-7 7 7-7 7 7',down:'m7 10 5 5 5-5',right:'m9 6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',out:'M7 17 17 7M7 7h10v10',search:'M15 15l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',folder:'M3 6h7l2 2h9v12H3z',archive:'M3 4h18v4H3zm2 4v12h14V8m-10 4h6',back:'m10 5-7 7 7 7M3 12h18',play:'m8 4 12 8-12 8z',pause:'M8 5v14M16 5v14',plus:'M12 5v14M5 12h14',attach:'m9 15 7-7a3 3 0 0 1 4 4l-9 9a5 5 0 0 1-7-7L14 4',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const orb='<span class="norma-mark" aria-hidden="true"><i></i><i></i></span>';
const avatar=a=>a.agent==='Norma'?orb:`<span class="agent-avatar" style="--person:${a.color}" title="${a.agent}" aria-label="${a.agent}"><i>${a.agent[0]}</i></span>`;
const tool=(action,ico,label,extra='')=>`<button class="icon-button" data-action="${action}" aria-label="${label}" title="${label}" ${extra}>${icon(ico)}</button>`;
function stateIcon(a){return `<span class="state-icon ${a.status}">${a.status==='done'||a.status==='needs'||a.status==='merge'?icon('check'):a.status==='running'?'<i></i>':icon('clock')}</span>`;}
function remember(){const feed=$('.thread-history');if(feed&&active())ctx(active()).scroll=feed.scrollTop;const left=$('.inbox-scroll');if(left)state.leftScroll=left.scrollTop;}
function render(){
 if(windowMode==='canvas'){document.title=tr('Norma · 画布窗口','Norma · Canvas');renderCanvas();return;}
 const focused=document.activeElement,focusId=focused?.dataset.testid,selection=focused?.selectionStart;const a=active();
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=tr('Norma · 任务收件箱','Norma · Task inbox');$('#inbox').setAttribute('aria-label',tr('Norma 任务收件箱','Norma task inbox'));
 $('#inbox-header').innerHTML=`<div class="brand">${orb}<strong>Norma</strong><span>${tr('任务','Tasks')}</span></div><button class="scope-trigger" data-menu="scope" aria-haspopup="dialog" aria-expanded="false">${icon('grid')}<span>${esc(scopeName())}</span>${icon('down')}</button><div class="header-tools">${windowMode==='tasks'?`<button class="window-switch" data-action="open-canvas">${icon('out')}${tr('画布','Canvas')}</button>`:''}${tool('search','search',tr('搜索任务','Search tasks'))}<button class="language" data-action="language" aria-label="${tr('切换为英文','Switch to Chinese')}">${lang==='zh'?'EN':'中'}</button><button class="shortcut" data-action="hide-inbox" title="${windowMode==='tasks'?tr('关闭 Norma 窗口','Close Norma window'):tr('收起任务页','Hide tasks')}"><kbd>⌘</kbd><kbd>⇧</kbd><kbd>Space</kbd></button>${tool('hide-inbox','close',windowMode==='tasks'?tr('关闭 Norma 窗口','Close Norma window'):tr('返回画布','Return to canvas'))}</div>`;
 $('#workspace').className=a?'workspace-layout split':'workspace-layout home';
 $('#workspace').innerHTML=`<section class="inbox-scroll"><div class="home-column">${!a?`<div class="hero"><h1><span>${tr('把工作交出去。','Leave the work to us.')}</span><br>${tr('回来就能看到','Come back to ')}<em>${tr('答案','answers')}</em><b>。</b></h1><p>${tr('Norma 协调你的 Agent，让工作各自向前。','Norma coordinates your agents. Work moves forward.')}<br>${tr('需要你时，答案和问题都在这里。','Find answers and decisions here when you return.')}</p></div>`:''}${composer()}${state.searchOpen?`<div class="task-search">${icon('search')}<input data-testid="task-search" placeholder="${tr('搜索任务、项目或 Agent','Search tasks, projects or agents')}" value="${esc(state.search)}">${tool('clear-search','close',tr('收起搜索','Close search'))}</div>`:''}${taskList()}</div></section>${a?thread(a):''}`;
 $('#inbox-footer').innerHTML=`<span>${t('local')}</span><div><button data-action="simulate">${tr('模拟一条新进展','Simulate an update')}</button><span class="footer-key">${tr('Esc 返回 · ⌘↵ 发送','Esc to go back · ⌘↵ to send')}</span>${windowMode==='tasks'?'':`<button data-action="video" aria-label="${tr('播放或暂停背景','Play or pause background')}" aria-pressed="${!$('#wallpaper').paused}">${icon($('#wallpaper').paused?'play':'pause')}</button>`}</div>`;
 $('.inbox-scroll').scrollTop=state.leftScroll;if(a){const feed=$('.thread-history');feed.scrollTop=ctx(a).scroll===Infinity?feed.scrollHeight:ctx(a).scroll;}
 if(focusId){const input=$(`[data-testid="${focusId}"]`);if(input){input.focus({preventScroll:true});if(selection!==null&&input.setSelectionRange)input.setSelectionRange(selection,selection);}}
 renderCanvas();
}
function composer(){const a=receiver(),dest=a||state.destination;return `<form class="new-composer" data-form="new"><textarea rows="2" data-testid="new-input" aria-label="${tr('新任务或指令','New work or direction')}" placeholder="${a?tr('给 '+a.agent+' 一个新的方向…','Give '+a.agent+' a new direction…'):tr('你想让助手做什么？','What would you like your assistant to do?')}">${esc(state.newDraft)}</textarea><div class="composer-bottom"><button type="button" class="recipient-trigger" data-menu="recipient" aria-haspopup="dialog" aria-expanded="false">${a?avatar(a):orb}<span>${a?a.agent:'Norma'}</span>${icon('down')}</button><button type="button" class="destination-trigger" data-menu="destination" aria-haspopup="dialog" aria-expanded="false" ${a?'disabled':''} title="${tr('新工作的目标项目；与查看范围独立','Destination project; separate from the viewing scope')}">${icon('folder')}<span>${spaceName(dest.space)}<i>/</i>${projects[dest.project].name}</span>${a?'':icon('down')}</button><button type="submit" class="send-button" data-testid="new-send" aria-label="${t('send')}" ${state.newDraft.trim()?'':'disabled'}>${icon('up')}</button></div></form>`;}
function workRow(a){return `<button class="work-row ${state.active===a.id?'selected':''}" data-work="${a.id}" aria-pressed="${state.active===a.id}">${stateIcon(a)}<span class="work-info"><strong>${esc(l(a.title))}</strong><small>${spaceName(a.space)}<i>/</i>${projects[a.project].name}${ctx(a).draft?`<span class="draft-label">${t('draft')}</span>`:''}</small></span><span class="work-latest ${a.status==='done'?'answered':''}">${a.status==='done'?t('done'):esc(l(a.summary))}</span>${a.unread?'<span class="unread-dot"></span>':''}${avatar(a)}</button>`;}
function taskList(){const list=listed();return `<div class="work-list">${['needs','running','waiting'].map(k=>{const rows=list.filter(a=>group(a)===k);return rows.length?`<section class="list-group" data-group="${k}"><h2>${t(k)}<span>${rows.length}</span></h2>${rows.map(workRow).join('')}</section>`:'';}).join('')}${!list.length?`<div class="empty-state">${icon('search')}<p>${tr('这个范围内没有匹配的工作','No matching work in this scope')}</p><button data-action="clear-filters">${tr('查看全部工作','Show all work')}</button></div>`:''}<section class="list-group archived" data-group="archive"><button class="archive-toggle" data-action="toggle-archive" aria-expanded="${state.archiveOpen}">${icon(state.archiveOpen?'down':'right')}${t('archive')}<span>${list.filter(a=>a.archived).length}</span></button>${state.archiveOpen?list.filter(a=>a.archived).map(workRow).join(''):''}</section></div>`;}
function thread(a){const c=ctx(a);return `<aside class="thread" aria-label="${tr('任务对话','Task conversation')}"><header class="thread-header"><div class="thread-heading">${stateIcon(a)}<h2>${esc(l(a.title))}</h2></div><div>${tool('locate','out',t('locate'),!a.card?'disabled':'')}${a.status==='done'?tool('archive','archive',a.archived?tr('移回收件箱','Move to inbox'):tr('归档这项工作','Archive this work')):''}${tool('close-thread','close',tr('返回任务列表','Back to task list'))}</div></header><div class="thread-context"><span>${spaceName(a.space)}<i>/</i>${projects[a.project].name}</span><span>${a.agent}<i>·</i>${l(a.engine)}</span></div>${!matchesScope(a)?`<div class="outside-scope">${tr('当前会话不在筛选范围内','This conversation is outside the current scope')}<button data-action="show-current">${tr('显示它','Show it')}</button></div>`:''}<div class="thread-history"><div class="thread-day">${tr('今天','Today')}</div><div class="message user">${esc(l(a.initial))}</div><article class="assistant-message"><div class="author">${avatar(a)}<strong>${a.agent}</strong><span>${tr('原卡片会话','Original card session')}</span></div><p>${esc(l(a.answer))}</p>${a.status==='needs'&&a.recommendation?`<div class="recommendation"><div>${orb}<strong>${tr('Norma 建议','Norma recommends')}</strong></div><p>${esc(l(a.recommendation))}</p><div class="recommendation-actions"><button data-action="accept" class="text-action primary">${icon('check')}${a.id==='navigation'?tr('标记已验收','Mark reviewed'):tr('按这个方案继续','Continue with this plan')}</button><button data-action="edit-recommendation" class="text-action">${tr('补充要求','Add direction')}</button></div></div>`:''}</article><details class="progress-details"><summary>${icon('right')}<span>${a.progress}/${a.total} ${tr('项已完成','steps complete')}</span><span class="thread-status ${a.status}">${t(a.status)}</span></summary><div>${a.steps.map((s,i)=>`<p class="${i<a.progress?'finished':''}">${icon(i<a.progress?'check':'clock')}${esc(l(s))}</p>`).join('')}</div></details>${c.messages.map(m=>m.role==='user'?`<div class="message user">${m.attachment?`<span class="file-bubble">${icon('attach')}${esc(m.attachment)}</span>`:''}${esc(l(m.text))}</div>`:`<article class="assistant-message reply"><div class="author">${avatar(a)}<strong>${a.agent}</strong>${m.sample?`<span>${tr('示例回执','Sample receipt')}</span>`:''}</div><p>${esc(l(m.text))}</p></article>`).join('')}</div><form class="thread-composer" data-form="thread">${c.attachment?`<div class="attachment-chip">${icon('attach')}${esc(c.attachment.name)}${tool('remove-attachment','close',tr('移除附件','Remove attachment'))}</div>`:''}<div><input type="file" id="attachment-input" hidden><button type="button" class="attach-button" data-action="attach" aria-label="${tr('添加本地附件','Attach a local file')}">${icon('plus')}</button><textarea rows="1" data-testid="thread-input" aria-label="${tr('给','Message ')}${a.agent}" placeholder="${tr('在这项任务中，给','In this task, message ')} ${a.agent} ${tr('发消息…','…')}">${esc(c.draft)}</textarea><button class="send-button" type="submit" data-testid="thread-send" aria-label="${t('send')}" ${c.draft.trim()?'':'disabled'}>${icon('up')}</button></div><small>${tr('与原卡片共用会话','Same conversation as the original card')}<span>⌘ ↵</span></small></form></aside>`;}
